 const visits=periodVisits(DATA.ziyaret||[]),plan=visits.length?100*visits.filter(x=>x.planned).length/visits.length:null;const active=reps.filter(x=>x.rn!=='BOS POZISYON');const freq=active.length?active.reduce((a,x)=>a+(x.freq||0),0)/active.length:null;const coverage=active.length?active.reduce((a,x)=>a+(x.coverage||0),0)/active.length:null;const selection=(DATA.sel||[]).length,riskBricks=IDX.bricks.filter(x=>rowPerf(x)<70).length;return {reps,h,s,real,gap:Math.max(0,h-s),visits,plan,freq,coverage,selection,riskBricks,bricks:IDX.bricks.length}
