function renderNav(){let section='';document.getElementById('nav').innerHTML=navItems.map(it=>{const [id,label,ic,sec]=it;let h='';if(sec&&sec!==section){section=sec;h=`<div class="nav-section">${sec}</div>`}return h+`<button class="nav-btn ${STATE.page===id?'active':''}" onclick="go('${id}')">${icon(ic)}<span>${label}</span>${id==='quality'&&qualityData().critical?`<span class="nav-badge">${qualityData().critical}</span>`:''}</button>`}).join('')}
