function periodBounds(k){const d=new Date(DATA.generatedAt||Date.now());let start,end;if(/^\d{2}\|\d{2}$/.test(k)){const [yy,mm]=k.split('|').map(Number);start=new Date(2000+yy,mm-1,1);end=new Date(2000+yy,mm,0)}else if(/^Q[1-4]$/.test(k)){const q=Number(k[1]),m=(q-1)*3;start=new Date(d.getFullYear(),m,1);end=new Date(d.getFullYear(),m+3,0)}else if(k==='H1'){start=new Date(d.getFullYear(),0,1);end=new Date(d.getFullYear(),6,0)}else if(k==='H2'){start=new Date(d.getFullYear(),6,1);end=new Date(d.getFullYear(),12,0)}else{return null}const asof=new Date(Math.min(Math.max(d.getTime(),start.getTime()),end.getTime()));const total=Math.floor((end-start)/86400000)+1,elapsed=Math.floor((asof-start)/86400000)+1,remaining=Math.max(0,total-elapsed);return {start,end,total,elapsed,remaining,asof}}
