let GROW_DRAFT={rep:'',scores:{},notes:{},evidence:{},managerNote:'',style:'destekleyici',startDate:'',endDate:'',doctorCount:'',pharmacyCount:'',bricks:[],goal:'',reality:'',options:'',way:'',managerComment:'',status:'Taslak'};
const PI_MEMORY_STORE={};
function piStoreGet(k){try{return window.localStorage.getItem(k)}catch(e){return Object.prototype.hasOwnProperty.call(PI_MEMORY_STORE,k)?PI_MEMORY_STORE[k]:null}}
function piStoreSet(k,v){try{window.localStorage.setItem(k,String(v))}catch(e){PI_MEMORY_STORE[k]=String(v)}}
function growSessions(){try{const current=piStoreGet('pi_grow_sessions_v3');if(current)return JSON.parse(current);const legacy=JSON.parse(piStoreGet('pi_grow_sessions')||'[]');return legacy.map((x,i)=>({id:'legacy'+i,created:x.created||'',status:'Aktarıldı',rep:x.rep||'',rn:x.rn||'',period:'',imsPeriod:'',startDate:x.created?.slice(0,10)||'',endDate:x.date||'',scores:{},notes:{},evidence:{},managerNote:'',style:'destekleyici',doctorCount:'',pharmacyCount:'',bricks:[],goal:x.goal||'',reality:x.reality||'',options:x.options||'',way:x.way||'',managerComment:'',avg:0,count:0,sectionScores:{}}))}catch(e){return[]}}
function saveGrowSessions(v){piStoreSet('pi_grow_sessions_v3',JSON.stringify(v))}
function growAllCriteria(){return GROW_SECTIONS.flatMap(s=>s.criteria.map(c=>({...c,section:s.name,sectionId:s.id})))}
function growInitRep(rn,force=false){if(!rn)return;if(!force&&GROW_DRAFT.rep===rn)return;const x=allRepMetrics().find(r=>r.rn===rn);const d=new Date(),e=new Date();e.setDate(e.getDate()+14);GROW_DRAFT={rep:rn,scores:{},notes:{},evidence:{},managerNote:'',style:'destekleyici',startDate:d.toISOString().slice(0,10),endDate:e.toISOString().slice(0,10),doctorCount:'',pharmacyCount:'',bricks:x?x.bricks.map(b=>b.brick):[],goal:'',reality:'',options:'',way:'',managerComment:'',status:'Taslak'};piStoreSet('pi_grow_last_rep',rn)}
function growRepChanged(rn){growInitRep(rn,true);renderPage()}
function growField(k,v){GROW_DRAFT[k]=v}
function growToggleBrick(b,on){const a=new Set(GROW_DRAFT.bricks||[]);on?a.add(b):a.delete(b);GROW_DRAFT.bricks=[...a]}
function growSetScore(id,v){GROW_DRAFT.scores[id]=v;renderPage();setTimeout(()=>document.getElementById('grow-'+id)?.scrollIntoView({block:'center'}),0)}
function growSetNote(id,v){GROW_DRAFT.notes[id]=v}
function growSetEvidence(cid,idx,v){GROW_DRAFT.evidence[cid]??={};GROW_DRAFT.evidence[cid][idx]=v;growRefreshEvidenceCount(cid)}
function growRefreshEvidenceCount(cid){const el=document.getElementById('evcount-'+cid);if(!el)return;const vals=Object.values(GROW_DRAFT.evidence[cid]||{}).filter(Boolean);el.textContent=vals.length?`${vals.length}/${(GROW_EVIDENCE[cid]||[]).length} kanıt`:'Kanıt seçilmedi'}
function growStats(){const all=growAllCriteria(),vals=all.map(c=>GROW_DRAFT.scores[c.id]).filter(v=>v);const avg=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0;const sections=GROW_SECTIONS.map(s=>{const sv=s.criteria.map(c=>GROW_DRAFT.scores[c.id]).filter(v=>v);return{id:s.id,name:s.name,count:sv.length,total:s.criteria.length,avg:sv.length?sv.reduce((a,b)=>a+b,0)/sv.length:0}});return{avg,count:vals.length,total:all.length,sections,strong:all.filter(c=>(GROW_DRAFT.scores[c.id]||0)>=4),expected:all.filter(c=>GROW_DRAFT.scores[c.id]===3),development:all.filter(c=>(GROW_DRAFT.scores[c.id]||0)>0&&(GROW_DRAFT.scores[c.id]||0)<=2)}}
function growAvgClass(v){return v>=4?'g4':v>=3?'g3':v>=2?'g2':'g1'}
function growEvidenceText(c){const defs=GROW_EVIDENCE[c.id]||[],st=GROW_DRAFT.evidence[c.id]||{},groups={gozlendi:[],kismen:[],gozlenmedi:[],dikkat:[]};defs.forEach((t,i)=>{if(st[i])groups[st[i]].push(t.toLowerCase())});const out=[];if(groups.gozlendi.length)out.push(groups.gozlendi.join(', ')+' gözlendi');if(groups.kismen.length)out.push(groups.kismen.join(', ')+' kısmen gözlendi');if(groups.gozlenmedi.length)out.push(groups.gozlenmedi.join(', ')+' gözlenmedi');if(groups.dikkat.length)out.push(groups.dikkat.join(', ')+' takip alanı olarak işaretlendi');return out.join('; ')}
function growAutoGenerate(){if(!GROW_DRAFT.rep)return toast('Önce temsilci seç');const st=growStats();if(st.count<3)return toast('Yorum üretmek için en az 3 kriter puanla');const x=allRepMetrics().find(r=>r.rn===GROW_DRAFT.rep);if(!x)return;const all=growAllCriteria(),ranked=all.filter(c=>GROW_DRAFT.scores[c.id]).sort((a,b)=>GROW_DRAFT.scores[b.id]-GROW_DRAFT.scores[a.id]);const strong=ranked.filter(c=>GROW_DRAFT.scores[c.id]>=4);const dev=ranked.filter(c=>GROW_DRAFT.scores[c.id]<=2);const expected=ranked.filter(c=>GROW_DRAFT.scores[c.id]===3);const evidenceSentences=ranked.map(c=>{const t=growEvidenceText(c);return t?`${c.section} / ${c.id.toUpperCase()}: ${t}.`:''}).filter(Boolean).slice(0,8);let comment=`${x.name} ile gerçekleştirilen ikili saha çalışmasında ${st.count}/${st.total} kriter değerlendirilmiş, genel ortalama 5 üzerinden ${st.avg.toFixed(2)} olarak hesaplanmıştır. `;comment+=`Ticari görünümde ${fmtTL(x.sales)} satış ve ${fmtPct(x.real)} realizasyon; saha disiplininde ${fmtPct(x.plan)} plan uyumu, ${fmtPct(x.coverage)} kaveraj ve ${fmtPct(x.freq)} frekans uyumu bulunmaktadır. `;if(strong.length)comment+=`Güçlü yönler ${[...new Set(strong.slice(0,3).map(c=>c.section))].join(', ')} başlıklarında yoğunlaşmaktadır; özellikle ${strong.slice(0,2).map(c=>c.text.split('.')[0].toLowerCase()).join(' ve ')} beklentinin üzerinde değerlendirilmiştir. `;if(expected.length)comment+=`${[...new Set(expected.map(c=>c.section))].join(', ')} alanları beklenen düzeydedir; bu puanlar gelişim bandı olarak değil, rol standardının karşılandığı seviye olarak yorumlanmıştır. `;if(dev.length)comment+=`Öncelikli gelişim alanları ${dev.slice(0,3).map(c=>c.section+' — '+c.text.split('.')[0].toLowerCase()).join('; ')} olarak belirlenmiştir. `;if(evidenceSentences.length)comment+=`Somut gözlem kırılımı: ${evidenceSentences.join(' ')} `;if(GROW_DRAFT.managerNote.trim())comment+=`Bölge müdürü saha notu: ${GROW_DRAFT.managerNote.trim()} `;comment+=dev.length?`Bir sonraki ikili çalışmada ${dev.slice(0,2).map(c=>GROW_ACTIONS[c.id]).join(' ')} sonuçları ölçülebilir biçimde takip edilecektir.`:`Mevcut standardın korunması ve güçlü davranışların diğer müşteri görüşmelerine sistematik biçimde taşınması takip edilecektir.`;
 const focus=dev.length?dev.slice(0,2):expected.slice(0,2);GROW_DRAFT.managerComment=comment;GROW_DRAFT.goal=dev.length?`${focus.map(c=>c.section).join(' ve ')} alanlarında davranış standardını en az “Beklenen Düzeyde” seviyesine taşımak; bununla birlikte plan uyumunu %85 ve frekans uyumunu %85 üzerine çıkarmak.`:`Güçlü saha davranışlarını sürdürülebilir hale getirmek ve bu standardı öncelikli bricklerde satış performansına yansıtmak.`;GROW_DRAFT.reality=`Real IMS: satış ${fmtTL(x.sales)}, hedef ${fmtTL(x.target)}, realizasyon ${fmtPct(x.real)}, açık ${fmtTL(x.gap)}. Plan uyumu ${fmtPct(x.plan)}, kaveraj ${fmtPct(x.coverage)}, frekans uyumu ${fmtPct(x.freq)}. Koçluk puanı ${st.avg.toFixed(2)}/5. ${dev.length?'Gelişim alanları: '+dev.slice(0,3).map(c=>c.section).join(', ')+'.':'Kritik düşük kriter bulunmuyor.'}`;GROW_DRAFT.options=(focus.length?focus.map((c,i)=>`${i+1}) ${GROW_ACTIONS[c.id]}`):['1) Güçlü davranışlardan birini ekip içinde paylaşmak.','2) Öncelikli üç brickte aynı standardı planlı biçimde uygulamak.']).join('\n');GROW_DRAFT.way=`İlk somut adımlar bir sonraki çalışma tarihine kadar uygulanacak. Takip tarihi ${GROW_DRAFT.endDate||'belirlenecek'}. Başarı göstergeleri: puanlanan gelişim kriterlerinde en az 3/5, plan uyumunda en az %85, frekans uyumunda en az %85 ve öncelikli bricklerde satış açığının azalması.`;renderPage();setTimeout(()=>document.getElementById('grow-output')?.scrollIntoView({behavior:'smooth',block:'start'}),0)}
function growBlankToExpected(){growAllCriteria().forEach(c=>{if(!GROW_DRAFT.scores[c.id])GROW_DRAFT.scores[c.id]=3});renderPage()}
function growSave(status){if(!GROW_DRAFT.rep)return toast('Temsilci seç');const st=growStats();if(status==='Tamamlandı'&&st.count<st.total)return toast('Tamamlamak için 13 kriterin tamamını puanla');if(st.count<1)return toast('En az 1 kriter puanla');if(!GROW_DRAFT.managerComment)growAutoGenerate();const x=allRepMetrics().find(r=>r.rn===GROW_DRAFT.rep);const sessions=growSessions(),id='g'+Date.now(),performanceBaseline=x?{real:x.real,plan:x.plan,coverage:x.coverage,freq:x.freq,gap:x.gap,sales:x.sales,target:x.target,period:STATE.period,imsPeriod:STATE.imsPeriod}:null;sessions.unshift({id,created:new Date().toISOString(),status,rep:x?.name||GROW_DRAFT.rep,rn:GROW_DRAFT.rep,period:monthLabel(STATE.period),imsPeriod:IDX.realSource?.sheet||DATA.real?.sheet||'',...JSON.parse(JSON.stringify(GROW_DRAFT)),performanceBaseline,avg:st.avg,count:st.count,sectionScores:Object.fromEntries(st.sections.map(s=>[s.id,s.avg]))});saveGrowSessions(sessions.slice(0,250));GROW_DRAFT.status=status;if(status==='Tamamlandı'&&x){const d={type:'GROW Takip',subject:x.name,owner:x.name,impact:x.gap,score:Math.max(0,3-st.avg)*20+(x.gap||0)/30000,reason:`Koçluk ortalaması ${st.avg.toFixed(2)}/5; takip tarihi ${GROW_DRAFT.endDate||'belirlenmedi'}`,action:GROW_DRAFT.way||'Koçluk taahhütlerini takip et.',target:'rep',id:x.rn,color:'#00a878'};DATA.manualActions=DATA.manualActions.filter(a=>!(a.type==='GROW Takip'&&a.id===x.rn));DATA.manualActions.unshift(d);DATA.actions[actionKey(d)]={status:'Açık',due:GROW_DRAFT.endDate||'',owner:x.name,targetValue:'Plan ve frekans ≥ %85',actualValue:'',customAction:GROW_DRAFT.way||d.action,note:GROW_DRAFT.managerComment||'',updated:new Date().toISOString()}}toast(status==='Tamamlandı'?'Koçluk ve takip aksiyonu kaydedildi':'Koçluk taslak olarak kaydedildi');renderPage()}
function growLoad(id){const s=growSessions().find(x=>x.id===id);if(!s)return;GROW_DRAFT={rep:s.rn,scores:s.scores||{},notes:s.notes||{},evidence:s.evidence||{},managerNote:s.managerNote||'',style:s.style||'destekleyici',startDate:s.startDate||'',endDate:s.endDate||'',doctorCount:s.doctorCount||'',pharmacyCount:s.pharmacyCount||'',bricks:s.bricks||[],goal:s.goal||'',reality:s.reality||'',options:s.options||'',way:s.way||'',managerComment:s.managerComment||'',status:s.status||'Taslak'};renderPage();window.scrollTo(0,0)}
function growDelete(id){const s=growSessions().filter(x=>x.id!==id);saveGrowSessions(s);toast('Koçluk kaydı silindi');renderPage()}
function growCopy(kind){const map={comment:GROW_DRAFT.managerComment,report:`G — Hedef\n${GROW_DRAFT.goal}\n\nR — Mevcut Durum\n${GROW_DRAFT.reality}\n\nO — Seçenekler\n${GROW_DRAFT.options}\n\nW — Taahhüt / Takip\n${GROW_DRAFT.way}`};copyText(map[kind]||'')}
function growScoreButtons(c){const v=GROW_DRAFT.scores[c.id]||0;return `<div class="grow-scale">${GROW_SCALE.map(s=>`<button type="button" class="grow-score ${s.cls} ${v===s.v?'active':''}" onclick="growSetScore('${c.id}',${s.v})"><b>${s.short}</b><span>${s.label}</span></button>`).join('')}</div>`}
function growEvidenceRows(c){return `<div class="grow-evidence"><div class="grow-evidence-head"><span>Somut davranış kanıtları</span><span id="evcount-${c.id}">${Object.values(GROW_DRAFT.evidence[c.id]||{}).filter(Boolean).length||0}/${(GROW_EVIDENCE[c.id]||[]).length} kanıt</span></div>${(GROW_EVIDENCE[c.id]||[]).map((t,i)=>`<div class="grow-evidence-row"><span>${esc(t)}</span><select onchange="growSetEvidence('${c.id}',${i},this.value)"><option value="">Değerlendirilmedi</option><option value="gozlendi" ${(GROW_DRAFT.evidence[c.id]||{})[i]==='gozlendi'?'selected':''}>Gözlendi</option><option value="kismen" ${(GROW_DRAFT.evidence[c.id]||{})[i]==='kismen'?'selected':''}>Kısmen gözlendi</option><option value="gozlenmedi" ${(GROW_DRAFT.evidence[c.id]||{})[i]==='gozlenmedi'?'selected':''}>Gözlenmedi</option><option value="dikkat" ${(GROW_DRAFT.evidence[c.id]||{})[i]==='dikkat'?'selected':''}>Dikkat edilecek</option></select></div>`).join('')}</div>`}
function growCriterion(c,i){const v=GROW_DRAFT.scores[c.id]||0;return `<div class="grow-criterion" id="grow-${c.id}"><div class="grow-criterion-top"><div class="grow-cno">${i}</div><div class="grow-ctext">${esc(c.text)}</div>${v?`<span class="grow-current ${growAvgClass(v)}">${v}/5 · ${GROW_LEVEL_TEXT[v]}</span>`:'<span class="grow-current">Puanlanmadı</span>'}</div>${growScoreButtons(c)}${growEvidenceRows(c)}<textarea class="grow-note" placeholder="Bu kritere ilişkin saha gözlemi, hekim/eczane örneği veya gelişim notu..." oninput="growSetNote('${c.id}',this.value)">${esc(GROW_DRAFT.notes[c.id]||'')}</textarea></div>`}
function growSummaryCard(st,x){return `<div class="card grow-summary-card"><div class="grow-summary-score ${growAvgClass(st.avg)}"><div>${st.count?st.avg.toFixed(2):'—'}</div><span>/5 genel ortalama</span></div><div class="grow-progress"><div style="width:${st.total?st.count/st.total*100:0}%"></div></div><div class="grow-complete">${st.count}/${st.total} kriter değerlendirildi</div><div class="grow-section-bars">${st.sections.map(s=>`<div class="grow-sbar"><div><span>${s.name}</span><b>${s.count?s.avg.toFixed(2):'—'}</b></div><div class="bar-track"><div class="bar-fill" style="width:${s.avg/5*100}%;background:${s.avg?pctColor(s.avg*20):'#dfe6ef'}"></div></div></div>`).join('')}</div>${x?`<div class="grow-commercial"><div class="grow-commercial-title">Gerçek performans bağlamı</div><div class="grow-commercial-grid"><div><span>Realizasyon</span><b>${fmtPct(x.real)}</b></div><div><span>Plan</span><b>${fmtPct(x.plan)}</b></div><div><span>Kaveraj</span><b>${fmtPct(x.coverage)}</b></div><div><span>Frekans</span><b>${fmtPct(x.freq)}</b></div><div><span>Satış açığı</span><b>${fmtTL(x.gap)}</b></div><div><span>Riskli brick</span><b>${x.riskBricks}</b></div></div><div class="grow-context-warning">Ticari metrikler davranış puanını otomatik belirlemez; yalnızca koçluk yorumuna bağlam sağlar.</div></div>`:''}<div class="grow-legend">${GROW_SCALE.map(s=>`<span class="${s.cls}"><b>${s.v}</b> ${s.label}</span>`).join('')}</div></div>`}
function growHistoryHtml(){const sessions=growSessions();if(!sessions.length)return '<div class="empty">Henüz kayıtlı koçluk yok</div>';return sessions.slice(0,30).map(s=>`<div class="grow-history-item"><div><div class="grow-history-name">${esc(s.rep)}</div><div class="grow-history-meta">${esc(s.startDate||s.created?.slice(0,10)||'—')} → ${esc(s.endDate||'—')} · ${esc(s.period||'')} · ${s.count||0}/13 kriter</div></div><span class="badge ${s.status==='Tamamlandı'?'b-green':'b-amber'}">${esc(s.status||'Taslak')}</span><b class="grow-history-score">${n(s.avg).toFixed(2)}</b><button class="link-btn" onclick="growLoad('${s.id}')">Aç</button><button class="link-btn red" onclick="growDelete('${s.id}')">Sil</button></div>`).join('')}
function renderGrow(){const reps=allRepMetrics().filter(x=>x.rn!=='BOS POZISYON');if(!GROW_DRAFT.rep){const last=piStoreGet('pi_grow_last_rep');if(last&&reps.some(r=>r.rn===last))growInitRep(last);else if(STATE.rep&&reps.some(r=>r.rn===STATE.rep))growInitRep(STATE.rep)}const x=GROW_DRAFT.rep?reps.find(r=>r.rn===GROW_DRAFT.rep):null,st=growStats();let no=0;return `${hero('GROW Koçluk ve Saha Değerlendirme','İlk dosyadaki 13 kriterli 1–5 puanlama sistemini gerçek performans verisi, davranış kanıtı ve takip aksiyonuyla birleştirir',`<button class="ghost-btn" onclick="exportGrowCSV()">Geçmişi indir</button><button class="ghost-btn" onclick="printPage()">Yazdır / PDF</button>`)}<div class="grow-layout"><div class="grow-main"><div class="card card-pad"><div class="grow-form-grid"><div class="form-group grow-span-2"><label>Temsilci</label><select onchange="growRepChanged(this.value)"><option value="">Temsilci seç</option>${reps.map(r=>`<option value="${esc(r.rn)}" ${GROW_DRAFT.rep===r.rn?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="form-group"><label>Başlangıç Tarihi</label><input type="date" value="${esc(GROW_DRAFT.startDate||'')}" oninput="growField('startDate',this.value)"></div><div class="form-group"><label>Takip Tarihi</label><input type="date" value="${esc(GROW_DRAFT.endDate||'')}" oninput="growField('endDate',this.value)"></div><div class="form-group"><label>Koçluk Tarzı</label><select onchange="growField('style',this.value)"><option value="destekleyici" ${GROW_DRAFT.style==='destekleyici'?'selected':''}>Destekleyici</option><option value="dogrudan" ${GROW_DRAFT.style==='dogrudan'?'selected':''}>Doğrudan</option><option value="mentor" ${GROW_DRAFT.style==='mentor'?'selected':''}>Mentor</option><option value="analitik" ${GROW_DRAFT.style==='analitik'?'selected':''}>Analitik</option><option value="kalibrasyon" ${GROW_DRAFT.style==='kalibrasyon'?'selected':''}>Kalibrasyon</option></select></div><div class="form-group"><label>Çalışılan Doktor</label><input type="number" min="0" value="${esc(GROW_DRAFT.doctorCount||'')}" oninput="growField('doctorCount',this.value)"></div><div class="form-group"><label>Çalışılan Eczane</label><input type="number" min="0" value="${esc(GROW_DRAFT.pharmacyCount||'')}" oninput="growField('pharmacyCount',this.value)"></div></div>${x?`<div class="grow-bricks"><div class="grow-bricks-title">Çalışılan brickler</div>${x.bricks.map(b=>`<label><input type="checkbox" ${GROW_DRAFT.bricks.includes(b.brick)?'checked':''} onchange="growToggleBrick('${esc(b.brick)}',this.checked)"> ${esc(b.brick)}</label>`).join('')}</div>`:''}<div class="form-group full"><label>Bölge Müdürü Saha Gözlem Notu</label><textarea class="field-area" placeholder="Somut hekim/eczane örneği, gözlenen davranış, ürün odağı, güçlü yön veya takip edilmesi gereken alan..." oninput="growField('managerNote',this.value)">${esc(GROW_DRAFT.managerNote||'')}</textarea></div></div>${GROW_DRAFT.rep?GROW_SECTIONS.map(s=>`<section class="card grow-section"><div class="grow-section-head"><div><span>${esc(s.name)}</span><b>${esc(s.title)}</b></div><div>${st.sections.find(z=>z.id===s.id)?.count||0}/${s.criteria.length} · ${st.sections.find(z=>z.id===s.id)?.count?(st.sections.find(z=>z.id===s.id).avg.toFixed(2)+'/5'):'—'}</div></div><div class="grow-section-body">${s.criteria.map(c=>growCriterion(c,++no)).join('')}</div></section>`).join(''):'<div class="card empty">Değerlendirmeye başlamak için temsilci seç.</div>'}</div><aside class="grow-side">${growSummaryCard(st,x)}${GROW_DRAFT.rep?`<div class="card card-pad grow-actions"><button class="ghost-btn" onclick="growBlankToExpected()">Boşları 3 ile doldur</button><button class="primary-btn" onclick="growAutoGenerate()">Veriden taslak oluştur</button><button class="ghost-btn" onclick="growSave('Taslak')">Taslak kaydet</button><button class="primary-btn" onclick="growSave('Tamamlandı')">Tamamla ve kaydet</button></div>`:''}</aside></div>${GROW_DRAFT.rep?`<div class="card grow-output" id="grow-output"><div class="card-head"><div><div class="card-title">Yönetici Yorumu ve GROW Çıktısı</div><div class="card-sub">Puan 3 “beklenen düzeyde” olarak nötr/olumlu yorumlanır; yalnızca 1–2 gelişim alanıdır.</div></div><button class="primary-btn" onclick="growAutoGenerate()">Yeniden oluştur</button></div><div class="grow-output-grid"><div class="grow-output-block"><div class="grow-output-title">SFA Yönetici Değerlendirme Yorumu <button class="link-btn" onclick="growCopy('comment')">Kopyala</button></div><textarea oninput="growField('managerComment',this.value)">${esc(GROW_DRAFT.managerComment||'')}</textarea></div><div class="grow-output-block"><div class="grow-output-title">G — Goal / Hedef</div><textarea oninput="growField('goal',this.value)">${esc(GROW_DRAFT.goal||'')}</textarea><div class="grow-output-title">R — Reality / Mevcut Durum</div><textarea oninput="growField('reality',this.value)">${esc(GROW_DRAFT.reality||'')}</textarea></div><div class="grow-output-block"><div class="grow-output-title">O — Options / Seçenekler</div><textarea oninput="growField('options',this.value)">${esc(GROW_DRAFT.options||'')}</textarea><div class="grow-output-title">W — Way Forward / Taahhüt</div><textarea oninput="growField('way',this.value)">${esc(GROW_DRAFT.way||'')}</textarea><button class="ghost-btn" onclick="growCopy('report')">GROW raporunu kopyala</button></div></div></div>`:''}${GROW_DRAFT.rep?growPerformanceFollowupHtml(GROW_DRAFT.rep):''}<div class="card grow-history"><div class="card-head"><div><div class="card-title">Koçluk Geçmişi</div><div class="card-sub">Tamamlanan ve taslak çalışmalar tarayıcıda yerel olarak saklanır</div></div></div><div class="grow-history-list">${growHistoryHtml()}</div></div>`}
function startGrow(rn){STATE.page='grow';STATE.rep=null;growInitRep(rn,true);renderNav();renderPage();window.scrollTo(0,0)}
function fillGrow(rn){growRepChanged(rn)}
function saveGrow(){growSave('Tamamlandı')}

function renderReports(){const reps=allRepMetrics().filter(x=>x.rn!=='BOS POZISYON');return `${hero('Rapor Merkezi','Bölge, temsilci, brick, ürün, müşteri, forecast ve aksiyon çıktılarını üretir',`<button class="primary-btn" onclick="downloadUpdatedHtml()">Güncellenmiş HTML indir</button>`)}<div class="grid-3">${[['Bölge Yönetici Özeti','PDF / Yazdır','printPage()'],['Temsilci Performans Karnesi','CSV','exportRepCSV()'],['Brick 360° Raporu','CSV','exportBrickCSV()'],['Ürün Performans Raporu','CSV','exportProductCSV()'],['Plan & Frekans Raporu','CSV','exportPlanCSV()'],['Forecast Raporu','CSV','exportForecastCSV()'],['Karar ve Aksiyon Listesi','CSV','exportDecisionCSV()'],['Müşteri / Seleksiyon Listesi','CSV','exportCustomerCSV()'],['Veri Kalite Kontrolü','CSV','exportQualityCSV()'],['WhatsApp Yönetici Özeti','Metin','copyWhatsApp()']].map(x=>`<div class="card card-pad"><div class="card-title">${x[0]}</div><div class="card-sub" style="margin:7px 0 14px">Çıktı: ${x[1]}</div><button class="ghost-btn" onclick="${x[2]}">Oluştur / İndir</button></div>`).join('')}</div><div class="section-space"></div><div class="card card-pad private-report-card"><div class="card-title">Temsilciye Özel Bağımsız HTML</div><div class="card-sub" style="line-height:1.7;margin:7px 0 12px">Yalnızca seçilen temsilcinin IMS, brick, ürün, saha KPI, aksiyon ve GROW geçmişini içeren paylaşılabilir dosya üretir. Diğer temsilcilerin verileri dosyaya eklenmez.</div><div style="display:flex;gap:8px;flex-wrap:wrap"><select class="field" id="reportRepSelect" style="min-width:260px"><option value="">Temsilci seç</option>${reps.map(x=>`<option value="${esc(x.rn)}">${esc(x.name)}</option>`).join('')}</select><button class="primary-btn" onclick="downloadSelectedRepHTML()">Özel HTML indir</button></div></div><div class="section-space"></div><div class="card card-pad"><div class="card-title">Paylaşım Notu</div><div class="card-sub" style="line-height:1.7;margin-top:8px">CSV dosyaları Excel ile açılır. PDF için yazdırma ekranında PDF olarak kaydet seçeneğini kullan. Güncellenmiş HTML; aksiyonları, snapshotları ve yeni yüklenen verileri dosyanın içine gömer.</div></div>`}
function renderUpload(){const cards=[['real','Real IMS','Güncel hedef / satış / realizasyon'],['kumule','Kümüle IMS','Pazar ve dönem birikimi'],['ytd','YTD IMS','Yıl içi kümülatif yapı'],['sel','Seleksiyon Listesi','Kullanıcı, Brick, Branş, Dr/Ecz Adı'],['ziyaret','Ziyaret Detay','Kullanıcı, Tarih, Planlı/Plansız'],['havuz','Havuz Raporu','Branş, Ünite, İl, Brick, Dr/Ecz Adı'],['siparis','Sipariş Detay','Eczane, ürün, adet, tarih']];return `${hero('Veri Yükle','Excel dosyaları tarayıcı içinde işlenir; hiçbir veri sunucuya gönderilmez',`<button class="primary-btn" onclick="downloadUpdatedHtml()">Veriyi HTML’ye göm ve indir</button>`)}<div class="card card-pad" style="margin-bottom:12px"><div class="upload-grid">${cards.map(x=>`<label class="drop"><input type="file" accept=".xlsx,.xls" onchange="handleUpload('${x[0]}',this.files[0],this)"><div class="drop-title">${x[1]}</div><div class="drop-sub">${x[2]}</div><div class="drop-status" id="status-${x[0]}">${uploadStatus(x[0])}</div></label>`).join('')}</div></div><div class="grid-2"><div class="card card-pad"><div class="card-title">Yükleme Sonrası</div><div class="card-sub" style="line-height:1.7;margin-top:8px">Dosya okunduğunda tüm indeksler yeniden kurulur. Yönetici Özeti, Temsilci 360°, Brick 360°, Plan & Frekans ve Veri Kalitesi anında güncellenir. Ardından güncellenmiş HTML’yi indirerek tek dosya halinde saklayabilirsin.</div></div><div class="card card-pad"><div class="card-title">Güvenlik</div><div class="card-sub" style="line-height:1.7;margin-top:8px">Programda API anahtarı bulunmaz. Analiz motoru bu dosyanın içindeki gerçek verilerle yerel çalışır. SheetJS kütüphanesi yüklenemezse mevcut gömülü veriler görüntülenmeye devam eder; yalnızca yeni Excel yükleme devre dışı kalır.</div></div></div>`}
function uploadStatus(k){const o=k==='real'?activeReal():k==='kumule'?DATA.kumule:k==='ytd'?DATA.ytd:DATA[k]||DATA[k==='sel'?'sel':k];if(Array.isArray(o))return `${fmtN(o.length)} kayıt gömülü`;return o?.fileName?`${esc(o.fileName)} · ${esc(o.sheet)}`:'Dosya seçilmedi'}
function renderPage(){const root=document.getElementById('content');const renderers={main:renderDashboard,decisions:renderDecisions,forecast:renderForecast,reps:renderReps,bricks:renderBricks,customers:renderCustomers,products:renderProducts,plan:renderPlan,archive:renderArchive,quality:renderQuality,grow:renderGrow,reports:renderReports,upload:renderUpload};root.innerHTML=(renderers[STATE.page]||renderDashboard)();if(STATE.page==='customers')renderCustomerBody();renderNav()}
function showModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('modalBg').classList.add('show')}
function closeModal(){document.getElementById('modalBg').classList.remove('show')}
function openDecision(i){const d=decisionRows()[i];if(!d)return;const r=d._rec;showModal(`<div class="detail-head"><div class="detail-avatar">A</div><div><div class="detail-name">${esc(d.type)} — ${esc(d.subject)}</div><div class="detail-meta">${esc(d.reason)}${d.impact?' · Etki '+fmtTL(d.impact):''}</div></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="tab-content"><div class="action-form"><div><label>Durum</label><select id="actStatus"><option ${r.status==='Açık'?'selected':''}>Açık</option><option ${r.status==='Devam Ediyor'?'selected':''}>Devam Ediyor</option><option ${r.status==='Beklemede'?'selected':''}>Beklemede</option><option ${r.status==='Tamamlandı'?'selected':''}>Tamamlandı</option></select></div><div><label>Son Tarih</label><input id="actDue" type="date" value="${esc(r.due)}"></div><div><label>Sorumlu</label><input id="actOwner" value="${esc(r.owner)}"></div><div><label>Hedef Değer</label><input id="actTarget" value="${esc(r.targetValue)}" placeholder="Örn. %85 / 50.000 TL"></div><div><label>Gerçekleşen</label><input id="actActual" value="${esc(r.actualValue)}"></div><div><label>Son Güncelleme</label><input value="${esc(r.updated?new Date(r.updated).toLocaleString('tr-TR'):'—')}" disabled></div><div class="full"><label>Aksiyon</label><textarea id="actText">${esc(r.customAction)}</textarea></div><div class="full"><label>Yönetici Notu</label><textarea id="actNote">${esc(r.note)}</textarea></div><div class="full" style="display:flex;gap:8px;flex-wrap:wrap"><button class="primary-btn" onclick="saveActionFromModal(${i})">Kaydet</button>${d.target!=='manual'?`<button class="ghost-btn" onclick="goDecisionTarget(${i})">Detay ekranını aç</button>`:`<button class="ghost-btn" onclick="deleteManualAction(${i})">Manuel aksiyonu sil</button>`}</div></div></div>`)}
function openLocalInsight(){const r=regionMetric(),reps=allRepMetrics().filter(x=>x.rn!=='BOS POZISYON').sort((a,b)=>b.risk-a.risk),bricks=allBrickMetrics().sort((a,b)=>b.gap-a.gap),q=qualityData();showModal(`<div class="detail-head"><div class="detail-avatar">AI</div><div><div class="detail-name">Yerel Yönetici Analizi</div><div class="detail-meta">IMS + seleksiyon + ziyaret + frekans + sipariş + veri kalitesi</div></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="tab-content"><div class="insight-grid"><div class="insight" style="--accent:${pctColor(r.real)}"><div class="insight-k">Genel Durum</div><div class="insight-v">Bölge ${fmtTL(r.s)} satışla ${fmtPct(r.real)} realizasyonda. Hedef açığı ${fmtTL(r.gap)}.</div></div><div class="insight" style="--accent:#7447f5"><div class="insight-k">Saha Disiplini</div><div class="insight-v">Plan uyumu ${fmtPct(r.plan)}, frekans uyumu ${fmtPct(r.freq)}, seçili müşteri kaverajı ${fmtPct(r.coverage)}.</div></div><div class="insight" style="--accent:${q.critical?'#ef3f53':'#00a878'}"><div class="insight-k">Veri Güveni</div><div class="insight-v">${q.critical?`${q.critical} kritik veri kalite başlığı var. Kümüle/YTD organizasyon uyumunu kontrol et.`:'Kritik veri kalite sorunu görünmüyor.'}</div></div></div><div class="section-space"></div><div class="card"><div class="card-head"><div class="card-title">Öncelik Sıralaması</div></div><div style="padding:12px;font-size:10px;line-height:1.8"><b>1. Temsilci:</b> ${esc(reps[0]?.name||'—')} — risk ${Math.round(reps[0]?.risk||0)}, realizasyon ${fmtPct(reps[0]?.real)}, frekans ${fmtPct(reps[0]?.freq)}.<br><b>2. Brick:</b> ${esc(bricks[0]?.name||'—')} — ${fmtTL(bricks[0]?.gap||0)} açık, ${fmtPct(bricks[0]?.real)} realizasyon.<br><b>3. Saha aksiyonu:</b> Frekans altında kalan seçili müşterileri yüksek satış açığı olan bricklerle eşleştir ve haftalık rotaya al.<br><b>4. Veri aksiyonu:</b> Güncel G3 Akdeniz Kümüle ve YTD dosyaları yüklenene kadar pazar/rakip yorumunu Real IMS ile sınırlı tut.</div></div></div>`)}
function runGlobalSearch(){const q=norm(document.getElementById('globalSearch').value);if(!q)return;const rep=allRepMetrics().find(x=>norm(x.name).includes(q));if(rep)return openRep(rep.rn);const brick=allBrickMetrics().find(x=>norm(x.name).includes(q));if(brick)return openBrick(brick.name);const prod=productMetrics().find(x=>norm(x.product).includes(q));if(prod){STATE.page='products';renderPage();setTimeout(()=>openProduct(prod.product),0);return}STATE.query=document.getElementById('globalSearch').value;STATE.page='customers';renderPage()}
function filterProvince(p){STATE.page='bricks';STATE.brick=null;renderPage();setTimeout(()=>{const s=document.getElementById('brickSearch');if(s){s.value=p;filterRows('brickTable',p)}},0)}
function csvDownload(name,headers,rows){const clean=v=>`"${String(v??'').replace(/"/g,'""')}"`;const csv='\ufeff'+[headers,...rows].map(r=>r.map(clean).join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function exportRepCSV(){csvDownload('PharmaInsight_Temsilci_360.csv',['Temsilci','Pozisyon','Hedef','Satış','Realizasyon','Plan Uyum','Kaveraj','Frekans','Seleksiyon','Sipariş','Eczane','Yanlış Brick','Risk'],allRepMetrics().map(x=>[x.name,x.row.positionCode,x.target,x.sales,x.real,x.plan,x.coverage,x.freq,x.sel.length,x.orders.length,x.pharmacies,x.wrong,x.risk]))}
function exportBrickCSV(){csvDownload('PharmaInsight_Brick_360.csv',['Brick','Temsilci','İl','Hedef','Satış','Açık','Realizasyon','Seçki','Havuz','Ziyaret','Plan Uyum','Sipariş','Adet'],allBrickMetrics().map(x=>[x.name,x.owner,province(x.name),x.target,x.sales,x.gap,x.real,x.sel.length,x.pool.length,x.visits,x.plan,x.orders.length,x.qty]))}
function exportProductCSV(){csvDownload('PharmaInsight_Urun_Performans.csv',['Ürün','Hedef','Satış','Açık','Realizasyon'],productMetrics().map(x=>[x.product,x.target,x.sales,x.gap,x.real]))}
function exportPlanCSV(){csvDownload('PharmaInsight_Plan_Frekans.csv',['Temsilci','Ziyaret','Planlı','Plan Uyum','Seleksiyon','Kaveraj','Frekans Uyumlu','Hedefli','Frekans'],allRepMetrics().map(x=>[x.name,x.visits.length,x.visits.filter(v=>v.planned).length,x.plan,x.sel.length,x.coverage,x.compliant,x.withTarget,x.freq]))}
function exportDecisionCSV(){csvDownload('PharmaInsight_Aksiyon_Merkezi.csv',['Tip','Konu','Sorumlu','Neden','Finansal Etki','Durum','Son Tarih','Hedef','Gerçekleşen','Aksiyon','Not'],decisionRows().map(x=>[x.type,x.subject,x._rec.owner,x.reason,x.impact,x._rec.status,x._rec.due,x._rec.targetValue,x._rec.actualValue,x._rec.customAction,x._rec.note]))}
function exportCustomerCSV(){const rows=customerRows();csvDownload('PharmaInsight_Musteri_360.csv',['Müşteri','Branş','Kurum','Brick','Temsilci'],rows.map(x=>[x.customer,x.specialty,x.institution,x.brick,x.rep]))}
function exportQualityCSV(){const q=qualityData();csvDownload('PharmaInsight_Veri_Kalitesi.csv',['Kontrol','Sayı/Değer','Durum'],[['Real organizasyon',q.realRegions.join(', '),'Temel'],['Kümüle organizasyon',q.kumRegions.join(', '),q.mismatchK?'Uyumsuz':'Uyumlu'],['YTD organizasyon',q.ytdRegions.join(', '),q.mismatchY?'Uyumsuz':'Uyumlu'],['Yanlış brick',q.wrong,q.wrong?'Kontrol':'Temiz'],['Eski temsilci kaydı',q.oldRep,q.oldRep?'Kontrol':'Temiz'],['Mükerrer seçki',q.duplicate,q.duplicate?'Kontrol':'Temiz'],['Havuzda bulunmayan',q.missingPool,q.missingPool?'Kontrol':'Temiz']])}
function exportGrowCSV(){const s=growSessions(),criteria=growAllCriteria();const headers=['Durum','Temsilci','Başlangıç','Takip','Dönem','IMS Dönemi','Genel Puan','Puanlanan Kriter',...criteria.map(c=>c.id.toUpperCase()+' - '+c.section),'Yönetici Yorumu','G','R','O','W'];const rows=s.map(x=>[x.status,x.rep,x.startDate,x.endDate,x.period,x.imsPeriod,x.avg,x.count,...criteria.map(c=>x.scores?.[c.id]||''),x.managerComment,x.goal,x.reality,x.options,x.way]);csvDownload('PharmaInsight_GROW_Gelismis.csv',headers,rows)}
function exportSingleRep(rn){const x=allRepMetrics().find(r=>r.rn===rn);if(!x)return;csvDownload(`Temsilci_${x.name}.csv`,['Metrik','Değer'],[['Hedef',x.target],['Satış',x.sales],['Realizasyon',x.real],['Plan uyum',x.plan],['Kaveraj',x.coverage],['Frekans',x.freq],['Seleksiyon',x.sel.length],['Sipariş',x.orders.length],['Risk',x.risk]])}
function exportSingleBrick(name){const x=allBrickMetrics().find(b=>norm(b.name)===norm(name));if(!x)return;csvDownload(`Brick_${x.name}.csv`,['Metrik','Değer'],[['Temsilci',x.owner],['Hedef',x.target],['Satış',x.sales],['Açık',x.gap],['Realizasyon',x.real],['Seçki',x.sel.length],['Havuz',x.pool.length],['Ziyaret',x.visits],['Sipariş',x.orders.length]])}
function printPage(){window.print()}
function copyText(t){navigator.clipboard?.writeText(t).then(()=>toast('Metin kopyalandı')).catch(()=>{const a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();document.execCommand('copy');a.remove();toast('Metin kopyalandı')})}
function copyWhatsApp(){const r=regionMetric(),top=decisionData().slice(0,3);copyText(`G3 Akdeniz Yönetici Özeti\nRealizasyon: ${fmtPct(r.real)} | Satış: ${fmtTL(r.s)} | Açık: ${fmtTL(r.gap)}\nPlan uyumu: ${fmtPct(r.plan)} | Frekans: ${fmtPct(r.freq)} | Kaveraj: ${fmtPct(r.coverage)}\nRiskli brick: ${r.riskBricks}/${r.bricks}\n\nİlk 3 öncelik:\n${top.map((x,i)=>`${i+1}. ${x.subject}: ${x.reason}`).join('\n')}`)}
function copyDecisionSummary(){copyText(decisionRows().slice(0,15).map((x,i)=>`${i+1}. ${x.type} — ${x.subject}: ${x.reason}. Durum: ${x._rec.status}. Son tarih: ${x._rec.due||'—'}. Aksiyon: ${x._rec.customAction}`).join('\n'))}
function downloadUpdatedHtml(){const clone=document.documentElement.cloneNode(true);clone.querySelector('#embeddedData').textContent=JSON.stringify(DATA).replace(/</g,'\\u003c');clone.querySelector('#loading')?.remove();clone.querySelector('#modalBg')?.classList.remove('show');const blob=new Blob(['<!DOCTYPE html>\n'+clone.outerHTML],{type:'text/html;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='PharmaInsight_Command_Center_v4_'+new Date().toISOString().slice(0,10)+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);toast('Güncellenmiş HTML indirildi')}
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
setTimeout(()=>{reindex();renderPage();document.getElementById('loading').style.display='none'},20);
